(* [comment removed for export] *)
Lemma repw_final : forall A A' m0 ws m,
  RepW A m0 ws m ->
  (forall x b, facts A' x b -> wlook ws x = Some b \/ (wlook ws x = None /\ facts A x b)) ->
  (forall x, dom A' x -> dom A x) ->
