  Lemma ts_lhu_factw : forall s (m0 : word -> option byte) ws a v (k : word -> M R) P,
    RepW A m0 ws (ms_mem s) -> WIN s -> has A (FCT a 2 v) -> wfree_range ws a 2 -> 0 <= v < 2^16 ->
