  Lemma ts_lw_wrw : forall s (m0 : word -> option byte) ws a v (k : word -> M R) P,
    RepW A m0 ws (ms_mem s) -> WIN s -> 0 <= a -> a + 4 <= alloc_ceiling -> 0 <= v ->
    (forall j, 0 <= j < 4 -> wlook ws (a + j) = Some (byte_of v j)) ->
    tsafe (k (w32 v) s) P ->
    tsafe ((x <- m_lw (Z_to_bv 64 a) ;; k x) s) P.
Proof.
