  Lemma ts_lbu_wrw : forall s (m0 : word -> option byte) ws a v (k : word -> M R) P,
    RepW A m0 ws (ms_mem s) -> WIN s -> 0 <= a -> a + 1 <= alloc_ceiling -> 0 <= v ->
    wlook ws a = Some (byte_of v 0) ->
    tsafe (k (Z_to_bv 64 (v mod 256)) s) P ->
